#include <iostream>
#include <string>

class Course {
private:
    std::string courseName;

public:
    void setCourseName(const std::string& name) {
        // Rule: maximum 10 characters, truncate if exceeded
        if (name.size() > 10) {
            courseName = name.substr(0, 10);
        } else {
            courseName = name;
        }
    }

    std::string getCourseName() const {
        return courseName;
    }

    void displayMessage() const {
        std::cout << "Course: " << getCourseName() << std::endl;
    }
};

int main() {
    Course myCourse;
    std::string input;
    if (std::getline(std::cin, input)) {
        myCourse.setCourseName(input);
        myCourse.displayMessage();
    }
    return 0;
}

#include <iostream>
#include <string>

// Emulating interface (header) and implementation (.cpp) in one translation unit
class BankAccount {
private:
    std::string owner;
    int balance{0};

public:
    explicit BankAccount(std::string initialOwner, int initialBalance);
    void deposit(int amount);
    int getBalance() const;
    std::string getOwner() const;
};

// Member function definitions outside class definition using ::
BankAccount::BankAccount(std::string initialOwner, int initialBalance)
    : owner(std::move(initialOwner)), balance(initialBalance > 0 ? initialBalance : 0) {}

void BankAccount::deposit(int amount) {
    if (amount > 0) {
        balance += amount;
    }
}

int BankAccount::getBalance() const {
    return balance;
}

std::string BankAccount::getOwner() const {
    return owner;
}

int main() {
    BankAccount acc("Alice", 150);
    acc.deposit(50);
    std::cout << acc.getOwner() << " balance: " << acc.getBalance() << std::endl;
    return 0;
}
